import React, { useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import logo from "../logo.jpeg"; // Your truck logo

const WorkerSplash = ({ onComplete }) => {
  useEffect(() => {
    const timer = setTimeout(onComplete, 4000);
    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#020617] flex items-center justify-center overflow-hidden relative">

      {/* 1. LAYER ONE: THE DEEP GLOW */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-[500px] h-[500px] bg-[#CAD23C] rounded-full blur-[120px] opacity-10 animate-pulse-glow" />
      </div>

      <AnimatePresence>
        <motion.div 
          className="relative z-10 flex flex-col items-center"
          initial={{ opacity: 0, scale: 0.8, filter: "blur(10px)" }}
          animate={{ 
            opacity: 1, 
            scale: 1, 
            filter: "blur(0px)",
          }}
          transition={{ 
            duration: 1.5, 
            ease: [0.22, 1, 0.36, 1] // Custom "Liquid" Bezier
          }}
          exit={{ 
            scale: 15, 
            opacity: 0, 
            filter: "blur(20px)",
            transition: { duration: 1.2, ease: "easeInOut" } 
          }}
        >
          {/* 2. THE TRUCK: Emerging from shadows */}
          <motion.img 
            src={logo} 
            alt="T2T Elite" 
            className="w-72 md:w-[450px] h-auto drop-shadow-[0_0_30px_rgba(202,210,60,0.2)]"
            initial={{ y: 20 }}
            animate={{ y: 0 }}
            transition={{ duration: 2, repeat: Infinity, repeatType: "mirror", ease: "easeInOut" }}
          />

          {/* 3. THE TEXT: Clean, Minimal, Tactical */}
          <motion.div 
            className="mt-12 text-center"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1 }}
          >
            <h1 className="text-white font-[900] tracking-[0.8em] text-sm uppercase opacity-40 italic">
              System <span className="text-[#CAD23C]">Initialization</span>
            </h1>

            {/* Smooth Progress Bar */}
            <div className="mt-6 w-48 h-[1px] bg-white/10 relative overflow-hidden mx-auto">
              <motion.div 
                className="absolute inset-0 bg-[#CAD23C]"
                initial={{ x: "-100%" }}
                animate={{ x: "0%" }}
                transition={{ duration: 2.5, ease: "easeInOut" }}
              />
            </div>
          </motion.div>
        </motion.div>
      </AnimatePresence>

      {/* 4. OVERLAY: High-End "Film Grain" for texture */}
      <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]" />
    </div>
  );
};

export default WorkerSplash;
